  completionId: string;
  requesterSessionKey: string;
  result: AgentSteeringResult;
  prompt: string;
  status: "in_progress";
  steeringLeaseId: string;
  leasedAt: number;
}

export interface AgentSteeringLeaseOptions {
  now?: number;
  staleAfterMs?: number;
}

export interface AgentSteeringLeaseOptionsWithSession extends AgentSteeringLeaseOptions {
  requesterSessionKey: string;
}

function resultText(result: AgentSteeringResult): string {
  for (const key of ["prompt", "output", "result", "content"] as const) {
    const value = result[key];
    if (typeof value === "string" && value.length > 0) return value;
  }
  return "";
}

function mergePrompt(result: AgentSteeringResult): string {
  const explicit = resultText(result);
  if (explicit) return explicit;
  try {
    return JSON.stringify(result);
  } catch {
    return String(result);
  }
}

function completionId(input: AgentSteeringEnqueueInput): string {
  return input.completionId ?? input.id ?? randomUUID();
}

function normalizedResult(result: AgentSteeringResult | string | undefined): AgentSteeringResult {
  return typeof result === "string" ? { output: result } : { ...(result ?? {}) };
}

/**
 * In-memory queue used to hand completed agent work to a steering session.
 *
 * A lease is an ownership token. Only the exact token returned by lease() can
 * acknowledge the work. Failed work may be released and is then eligible for a
 * later lease; cancelling or terminating work makes it permanently ineligible.
 */
export class AgentSteeringQueue {
  private readonly items = new Map<string, AgentSteeringItem>();

  constructor(private readonly nowProvider: () => number = Date.now) {}

  enqueue(input: AgentSteeringEnqueueInput): AgentSteeringItem {
    const now = input.createdAt ?? this.nowProvider();
    const id = completionId(input);
    const existing = this.items.get(id);
    if (existing) return { ...existing, result: { ...existing.result } };

    const result = normalizedResult(input.result);
    const item: AgentSteeringItem = {
      id,
      completionId: id,
      requesterSessionKey: input.requesterSessionKey,
      result,
      status: input.status === "suspended" ? "suspended" : "pending",
      prompt: mergePrompt(result),
      createdAt: now,
      updatedAt: input.updatedAt ?? now,
    };
    this.items.set(id, item);
    return { ...item, result: { ...item.result } };
  }

  listPending(requesterSessionKey: string): AgentSteeringItem[] {
    return [...this.items.values()]
      .filter(
        (item) =>
          item.requesterSessionKey === requesterSessionKey &&
          (item.status === "pending" || item.status === "suspended"),
      )
      .map((item) => ({ ...item, result: { ...item.result } }));
  }

  lease(
    requesterSessionKey: string,
    options: AgentSteeringLeaseOptions = {},
  ): AgentSteeringLease | null {
    const now = options.now ?? this.nowProvider();
    const staleAfterMs = options.staleAfterMs ?? STALE_LEASE_MS;
    const candidate = [...this.items.values()]
      .filter(
        (item) =>
          item.requesterSessionKey === requesterSessionKey &&
          (item.status === "pending" ||
            item.status === "suspended" ||
            (item.status === "in_progress" &&
              now - (item.leaseStartedAt ?? item.updatedAt) > staleAfterMs)),
      )
      .sort((a, b) => a.createdAt - b.createdAt || a.id.localeCompare(b.id))[0];

    if (!candidate) return null;

    const leaseId = randomUUID();
    candidate.status = "in_progress";
    candidate.steeringLeaseId = leaseId;
    candidate.leaseStartedAt = now;
    candidate.updatedAt = now;

    return {
      leaseId,
      steeringLeaseId: leaseId,
      id: candidate.id,
      completionId: candidate.completionId,
      requesterSessionKey: candidate.requesterSessionKey,
      result: { ...candidate.result },
      prompt: candidate.prompt ?? mergePrompt(candidate.result),
      status: "in_progress",
      leasedAt: now,
    };
  }

  ack(leaseId: string, requesterSessionKey?: string): boolean {
    const item = this.findLeased(leaseId, requesterSessionKey);
    if (!item) return false;
    item.status = "delivered";
    item.updatedAt = this.nowProvider();
    item.steeringLeaseId = undefined;
    item.leaseStartedAt = undefined;
    return true;
  }

  release(leaseId: string, requesterSessionKey?: string): boolean {
    const item = this.findLeased(leaseId, requesterSessionKey);
    if (!item) return false;
    item.status = "pending";
    item.updatedAt = this.nowProvider();
    item.steeringLeaseId = undefined;
    item.leaseStartedAt = undefined;
    return true;
  }

  cancel(idOrLeaseId: string, requesterSessionKey?: string): boolean {
    const item = this.items.get(idOrLeaseId);
    if (!item) return false;
    if (requesterSessionKey !== undefined && item.requesterSessionKey !== requesterSessionKey) {
      return false;
    }
    if (item.status === "delivered" || item.status === "discarded" || item.status === "failed") {
      return false;
    }
    item.status = "discarded";
    item.updatedAt = this.nowProvider();
    item.steeringLeaseId = undefined;
    item.leaseStartedAt = undefined;
    return true;
  }

  terminate(id: string, requesterSessionKey?: string): boolean {
    const item = this.items.get(id);
    if (!item) return false;
    if (requesterSessionKey !== undefined && item.requesterSessionKey !== requesterSessionKey) {
      return false;
    }
    if (item.status === "delivered" || item.status === "discarded" || item.status === "failed") {
      return false;
    }
    item.status = "failed";
    item.updatedAt = this.nowProvider();
    item.steeringLeaseId = undefined;
    item.leaseStartedAt = undefined;
    return true;
  }

  get(id: string): AgentSteeringItem | undefined {
    const item = this.items.get(id);
    return item ? { ...item, result: { ...item.result } } : undefined;
  }

  private findLeased(
    leaseId: string,
    requesterSessionKey?: string,
  ): AgentSteeringItem | undefined {
    const item = [...this.items.values()].find(
      (candidate) =>
        candidate.status === "in_progress" &&
        candidate.steeringLeaseId === leaseId &&
        (requesterSessionKey === undefined ||
          candidate.requesterSessionKey === requesterSessionKey),
    );
    return item;
  }
}

export const agentSteeringQueue = new AgentSteeringQueue();

export function enqueueAgentSteering(
  input: AgentSteeringEnqueueInput,
): AgentSteeringItem {
  return agentSteeringQueue.enqueue(input);
}

export function listPendingAgentSteering(
  requesterSessionKey: string,
): AgentSteeringItem[] {
  return agentSteeringQueue.listPending(requesterSessionKey);
}

export function leaseAgentSteering(
  requesterSessionKey: string,
  options: AgentSteeringLeaseOptions = {},
): AgentSteeringLease | null {
  return agentSteeringQueue.lease(requesterSessionKey, options);
}

export function ackAgentSteering(leaseId: string, requesterSessionKey?: string): boolean {
  return agentSteeringQueue.ack(leaseId, requesterSessionKey);
}

export function releaseAgentSteering(leaseId: string, requesterSessionKey?: string): boolean {
  return agentSteeringQueue.release(leaseId, requesterSessionKey);
}

export function cancelAgentSteering(id: string, requesterSessionKey?: string): boolean {
  return agentSteeringQueue.cancel(id, requesterSessionKey);
}

export function terminateAgentSteering(id: string, requesterSessionKey?: string): boolean {
  return agentSteeringQueue.terminate(id, requesterSessionKey);
}

export const enqueueSteeringCompletion = enqueueAgentSteering;
export const listPendingSteeringCompletions = listPendingAgentSteering;
export const leaseSteeringCompletion = leaseAgentSteering;
export const ackSteeringCompletion = ackAgentSteering;
export const releaseSteeringCompletion = releaseAgentSteering;
export const cancelSteeringCompletion = cancelAgentSteering;
